# Verify the solution
solution = [6, 2, 0, 1, 7, 0, 7, 1, 7, 5, 6, 2, 3, 4, 3, 4, 0, 1, 2, 3, 4, 5, 5, 6, 4, 7, 6, 7, 3, 1, 6, 2, 4, 0, 0, 4, 5, 3, 1, 2, 0, 1, 2, 3, 5, 6, 7, 5, 4, 1, 6, 4, 7, 4, 5, 6, 6, 7, 5, 0, 0, 2, 2, 3, 0, 1, 2, 3, 1, 3, 5, 7, 5, 6, 7, 2, 7, 4, 4, 3, 0, 3, 2, 4, 1, 0, 7, 1, 0, 1, 2, 3, 5, 6, 5, 6, 6, 6, 3, 3, 4, 7, 6, 0, 5, 2, 1, 0, 2, 1, 0, 4, 4, 1, 2, 3, 5, 5, 7, 7]

num_golfers = 24
num_weeks = 5
num_groups = 8
group_size = 3

# Parse solution into weeks
weeks = []
for w in range(num_weeks):
    week = solution[w*24:(w+1)*24]
    weeks.append(week)

# Check each week has valid groups
for w in range(num_weeks):
    groups = {}
    for p in range(num_golfers):
        g = weeks[w][p]
        if g not in groups:
            groups[g] = []
        groups[g].append(p)

    # Check all 8 groups exist with 3 golfers each
    for g in range(num_groups):
        if g not in groups:
            print(f"Week {w}: Group {g} missing!")
        elif len(groups[g]) != group_size:
            print(f"Week {w}: Group {g} has {len(groups[g])} golfers!")

    # Check all golfers assigned
    all_golfers = set()
    for g in groups:
        all_golfers.update(groups[g])
    if len(all_golfers) != num_golfers:
        print(f"Week {w}: Not all golfers assigned!")

# Check no pair appears together more than once
pair_count = {}
for w in range(num_weeks):
    groups = {}
    for p in range(num_golfers):
        g = weeks[w][p]
        if g not in groups:
            groups[g] = []
        groups[g].append(p)

    for g in groups:
        members = groups[g]
        for i in range(len(members)):
            for j in range(i+1, len(members)):
                pair = (min(members[i], members[j]), max(members[i], members[j]))
                if pair in pair_count:
                    print(f"Pair {pair} appears in weeks {pair_count[pair]} and {w}!")
                pair_count[pair] = w

print(f"Total unique pairs: {len(pair_count)}")
print(f"Expected pairs: {num_golfers * (num_golfers - 1) // 2}")
print(f"Pairs per week: {num_groups * group_size * (group_size - 1) // 2}")
print(f"Total pairs across all weeks: {num_weeks * num_groups * group_size * (group_size - 1) // 2}")
print("Verification complete!")
